import RNA, random
target = "(((((....)).((((((....)))..((((.((((..(((....)))(((.((....))(((...)))((....)).)))(((....)))..)))).((((..(((....)))(((.((....))(((...)))((....)).)))(((....)))..)))).((((..(((....)))(((.((....))(((...)))((....)).)))(((....)))..)))).((((..(((....)))(((.((....))(((...)))((....)).)))(((....)))..)))).((((..(((....)))(((.((....))(((...)))((....)).)))(((....)))..)))).))))..(((....)))))).((....)))))"

stack=[]
pairs={}
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop()
        pairs[j]=i; pairs[i]=j

# Find hairpin loops
loops=[]
for i,j in pairs.items():
    if i<j and all(c=='.' for c in target[i+1:j]):
        loops.append((i,j))

seq=['A']*len(target)
for (i,j) in loops:
    L=j-i-1
    seq[i]='G'; seq[j]='C'
    if L==4: seq[i+1:i+5]=list("GAAA")
    elif L==3: seq[i+1:i+4]=list("GAA")
    elif L==2: seq[i+1:i+3]=list("GA")

# Set all other stem pairs to G-C
for i,j in pairs.items():
    if i<j:
        seq[i]='G'; seq[j]='C'

# Now use RNA.inverse_fold with this as start, allow it to refine
# Use RNA.inverse_fold which returns sequence
fc = RNA.fold_compound(target)
# inverse_fold from start
start = "".join(seq)
res = fc.inverse_fold(start, target)
print(res[0])
ss,mfe = RNA.fold(res[0])
print(ss)
print("match", ss==target, RNA.bp_distance(ss,target))
